import 'dart:io';

import 'package:drift/drift.dart' hide isNull;
import 'package:drift/native.dart';
import 'package:drift_dev/api/migrations_native.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:persistence/src/database/app_database.dart';

import 'generated_migrations/schema.dart';
import 'generated_migrations/schema_v1.dart' as v1;
import 'generated_migrations/schema_v2.dart' as v2;

void main() {
  late SchemaVerifier verifier;

  setUpAll(() {
    // GeneratedHelper() was generated by drift from drift_schemas/ — the
    // committed v1/v2 snapshots (`dart run drift_dev schema generate
    // --data-classes --companions drift_schemas/ test/generated_migrations/`).
    verifier = SchemaVerifier(GeneratedHelper());
  });

  test('v1 to v2 with populated rows: every row survives, every value intact, '
      'new column is null', () async {
    final schema = await verifier.schemaAt(1);

    final oldDb = v1.DatabaseAtV1(schema.newConnection());
    await oldDb.into(oldDb.playbackProgress).insert(
          v1.PlaybackProgressCompanion.insert(
            mediaId: 'movie-1',
            positionMs: 60000,
            durationMs: 7200000,
            updatedAt: 1700000000000,
            // The schema-snapshot-generated companion represents the old
            // BoolColumn at the raw SQL (INTEGER 0/1) level rather than as
            // Dart bool.
            completed: 0,
            audioTrackId: const Value('audio-1'),
            subtitleTrackId: const Value('sub-1'),
          ),
        );
    await oldDb.close();

    final db = AppDatabase(schema.newConnection());
    await verifier.migrateAndValidate(db, 2);
    await db.close();

    final migratedDb = v2.DatabaseAtV2(schema.newConnection());
    final row = await migratedDb.select(migratedDb.playbackProgress).getSingle();
    expect(row.mediaId, 'movie-1');
    expect(row.positionMs, 60000);
    expect(row.durationMs, 7200000);
    expect(row.updatedAt, 1700000000000);
    // Schema-snapshot-generated classes represent BoolColumn at the raw
    // SQL (INTEGER 0/1) level, same as the v1 companion above.
    expect(row.completed, 0);
    expect(row.audioTrackId, 'audio-1');
    expect(row.subtitleTrackId, 'sub-1');
    expect(row.lastPlayedSourceKey, isNull);
    await migratedDb.close();
  });

  test('onCreate at v2 produces a schema identical to migrating from v1', () async {
    // migrateAndValidate compares the migrated schema's CREATE statements
    // against what onCreate-at-2 would produce and throws SchemaMismatch on
    // any unexpected difference — starting from an *empty* v1 database
    // isolates that check from the row-survival assertion above (the
    // Phase's own pitfall: a migration test on an empty database "passes
    // while the real migration drops every row" — this test only proves
    // schema shape, the other one proves data).
    final schema = await verifier.schemaAt(1);
    final db = AppDatabase(schema.newConnection());
    await verifier.migrateAndValidate(db, 2);
    await db.close();
  });

  test('a deliberately broken migration produces an error and leaves the file unchanged',
      () async {
    final tempDir = Directory.systemTemp.createTempSync('migration_broken_test_');
    final file = File('${tempDir.path}/broken.db');
    addTearDown(() => tempDir.deleteSync(recursive: true));

    // A real, fully-created v2 database with a row in it.
    final seed = AppDatabase(NativeDatabase(file));
    await seed.into(seed.playbackProgress).insert(
          PlaybackProgressCompanion.insert(
            mediaId: 'movie-1',
            positionMs: 1000,
            durationMs: 2000,
            updatedAt: 1700000000000,
            completed: false,
          ),
        );
    await seed.close();
    final bytesBefore = file.readAsBytesSync();

    // Reopen the same file with a schema one version ahead whose upgrade
    // step always throws — simulating a bug in a future migration.
    final broken = _BrokenMigrationDatabase(NativeDatabase(file));
    await expectLater(
      () => broken.customSelect('SELECT 1').getSingleOrNull(),
      throwsA(anything),
    );
    await broken.close();

    expect(file.readAsBytesSync(), bytesBefore);
  });
}

class _BrokenMigrationDatabase extends AppDatabase {
  _BrokenMigrationDatabase(super.executor);

  @override
  int get schemaVersion => 3;

  @override
  MigrationStrategy get migration => MigrationStrategy(
        onCreate: (m) => m.createAll(),
        onUpgrade: (m, from, to) async {
          await transaction(() async {
            await customStatement('ALTER TABLE playback_progress ADD COLUMN bogus TEXT');
            throw StateError('simulated migration bug');
          });
        },
      );
}
